1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
24	    @Mapping(target = "initials",
25	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
26	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
27	    @Mapping(target = "locality", expression = "java(locality(owner))")
28	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
29	    @Mapping(target = "bulkSignupWarning",
30	        expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
31	    @Mapping(target = "capacityWarning",
32	        expression = "java(Boolean.TRUE.equals(owner.getCapacityWarning()))")
33	    @Mapping(target = "possibleDuplicate",
34	        expression = "java(Boolean.TRUE.equals(owner.getPossibleDuplicate()))")
35	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
36	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
37	    @Mapping(target = "telephoneDisplay",
38	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones.toDisplay(owner.getTelephone()))")
39	    @Mapping(target = "identityKey",
40	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
41	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
42	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
43	    OwnerDto toOwnerDto(Owner owner);
44	
45	    /**
46	     * Derives the owner's segment, formatted {@code <TIER>_<AREA>}. TIER is
47	     * {@code PREMIUM} when the membershipLevel is 3 or more, otherwise
48	     * {@code STANDARD}. AREA is {@code METRO} when the owner's locality is a known
49	     * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
50	     */
51	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
52	        Integer level = owner.getMembershipLevel();
53	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
54	        boolean metro = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
55	            .isKnownRegion(locality(owner));
56	        String area = metro ? "METRO" : "REGIONAL";
57	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
58	    }
59	
60	    /**
61	     * The canonical API path to this owner, formatted {@code /api/owners/<id>}. Null
62	     * until the owner has been assigned an id.
63	     */
64	    default String selfLink(Owner owner) {
65	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
66	    }
67	
68	    /**
69	     * Derives the owner's age band from the {@code birthDate} measured against the
70	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to
71	     * 64 inclusive and {@code SENIOR} at 65 or over. Null when no birth date is present.
72	     */
73	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
74	        java.time.LocalDate birthDate = owner.getBirthDate();
75	        if (birthDate == null) {
76	            return null;
77	        }
78	        java.time.LocalDate reference = owner.getRegistrationDate() != null
79	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
80	        int years = java.time.Period.between(birthDate, reference).getYears();
81	        if (years < 18) {
82	            return OwnerDto.AgeBandEnum.MINOR;
83	        }
84	        if (years < 65) {
85	            return OwnerDto.AgeBandEnum.ADULT;
86	        }
87	        return OwnerDto.AgeBandEnum.SENIOR;
88	    }
89	
90	    /**
91	     * Composes the owner's salutation from the optional title and the last name:
92	     * {@code <title> <lastName>} when a title is present (non-null and not blank),
93	     * or just the last name when no title was supplied.
94	     */
95	    default String salutation(Owner owner) {
96	        String title = owner.getTitle();
97	        if (title != null && !title.isBlank()) {
98	            return title + " " + owner.getLastName();
99	        }
100	        return owner.getLastName();
101	    }
102	
103	    /**
104	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email
105	     * address is present (non-null and not blank), otherwise {@code PHONE}.
106	     */
107	    default String contactPreference(Owner owner) {
108	        String email = owner.getEmail();
109	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
110	    }
111	
112	    /**
113	     * Derives the owner's locality (region) from the owner's {@code memberId}
114	     * identity ({@code <REGION><FY><HASH8><CHK>}): the locality is the {@code REGION}
115	     * segment of that identity. When the member id has not been assigned yet, it falls
116	     * back to deriving the region directly (see
117	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion}).
118	     */
119	    default String locality(Owner owner) {
120	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
121	            .regionFromMemberId(owner.getMemberId());
122	        return region != null ? region
123	            : org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.regionOf(owner);
124	    }
125	
126	    /**
127	     * Derives the owner's IANA timezone name from the owner's locality/region via the
128	     * pinned region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
129	     * QLD->Australia/Brisbane). Null when the region has no mapped timezone.
130	     */
131	    default String timezone(Owner owner) {
132	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion
133	            .timezoneOfRegion(locality(owner));
134	    }
135	
136	    /**
137	     * Derives the owner's fiscal year, formatted {@code FY<YY>}, from the
138	     * (business-day-adjusted) registration date. The fiscal year starts on 1 July and
139	     * is named by the calendar year it ends in. Null when no registration date is set.
140	     */
141	    default String fiscalYear(Owner owner) {
142	        if (owner.getRegistrationDate() == null) {
143	            return null;
144	        }
145	        return org.springframework.samples.petclinic.rest.function.owner.OwnerFiscalYear
146	            .fiscalYearLabel(owner.getRegistrationDate());
147	    }
148	
149	    Owner toOwner(OwnerDto ownerDto);
150	
151	    @Mapping(target = "id", ignore = true)
152	    @Mapping(target = "pets", ignore = true)
153	    Owner toOwner(OwnerFieldsDto ownerDto);
154	
155	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
156	
157	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
158	
159	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
160	        OwnerPageDto ownerPageDto = new OwnerPageDto();
161	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
162	        ownerPageDto.setPage(ownerPage.getNumber());
163	        ownerPageDto.setSize(ownerPage.getSize());
164	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
165	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
166	        return ownerPageDto;
167	    }
168	}
