1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a city approaching its capacity limit on create: sets the owner's
9	 * {@code capacityWarning} to {@code true} when the owner's city already contains
10	 * between 40 and 49 existing owners (inclusive) — approaching the hard capacity limit
11	 * of 50 — otherwise {@code false}. Shares the city-matching predicate with
12	 * {@link RejectCityAtCapacity} via {@link OwnerCityCount}.
13	 *
14	 * <p>Runs before {@link SaveOwner}, so the owner being created is not counted, and
15	 * after {@link RejectCityAtCapacity}, which has already escalated a 409 for any city at
16	 * (or over) 50 — so by the time this step runs the count is at most 49.
17	 */
18	public class FlagCityCapacityWarning {
19	
20	    private static final int WARN_THRESHOLD = 40;
21	
22	    private static final int CITY_CAPACITY = 50;
23	
24	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
25	        long count = OwnerCityCount.sharingCity(ownerRepository, owner.getCity());
26	        owner.setCapacityWarning(count >= WARN_THRESHOLD && count < CITY_CAPACITY);
27	    }
28	}
