1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Flags a bulk signup on create: sets the owner's {@code bulkSignupWarning} to
9	 * {@code true} when more than 80 owners already share the new owner's
10	 * (business-day-adjusted) registration date, as counted by
11	 * {@link Owner#getRegistrationDate()}, otherwise {@code false}. Runs before
12	 * {@link SaveOwner}, so the owner being created is not counted — the same
13	 * accumulation path as {@link RejectOverDailyLimit}, at a lower threshold.
14	 */
15	public class FlagBulkSignup {
16	
17	    private static final int BULK_THRESHOLD = 80;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        long count = OwnerDailyCount.sharingRegistrationDate(ownerRepository, owner.getRegistrationDate());
21	        owner.setBulkSignupWarning(count > BULK_THRESHOLD);
22	    }
