2	
3	import java.util.Set;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Email is optional on an owner. When absent (null or blank) this step does nothing.
12	 * When present it must be a syntactically valid address, otherwise it escalates as a
13	 * 400 via {@link InvalidEmailException}. A valid address is stored back on the owner
14	 * lower-cased (so it is persisted and returned lower-cased).
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    /**
19	     * Pragmatic syntactic check: a non-empty local part, a single '@', then a domain
20	     * with at least one dot and no whitespace.
21	     */
22	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
23	
24	    /**
25	     * Disposable email domains that are rejected outright (400). A throwaway address on
26	     * one of these providers is not acceptable contact detail for an owner.
27	     */
28	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
29	            "mailinator.com", "tempmail.com", "guerrillamail.com");
30	
31	    public void service(@Val Owner owner) throws InvalidEmailException {
32	        String email = owner.getEmail();
33	        if (email == null || email.isBlank()) {
34	            return;
35	        }
36	        String trimmed = email.trim();
37	        if (!EMAIL.matcher(trimmed).matches()) {
38	            throw new InvalidEmailException("Email must be a syntactically valid address");
39	        }
40	        String lowered = trimmed.toLowerCase();
41	        String domain = lowered.substring(lowered.indexOf('@') + 1);
42	        if (DISPOSABLE_DOMAINS.contains(domain)) {
43	            throw new InvalidEmailException("Email domain is not allowed: " + domain);
44	        }
45	        owner.setEmail(lowered);
46	    }
47	}
